const fs = require('fs');

function solve() {
    const input = fs.readFileSync(0, 'utf-8');
    let pos = 0;

    function nextToken() {
        while (pos < input.length && input.charCodeAt(pos) <= 32) {
            pos++;
        }
        if (pos >= input.length) return null;
        const start = pos;
        while (pos < input.length && input.charCodeAt(pos) > 32) {
            pos++;
        }
        return input.slice(start, pos);
    }

    const L_str = nextToken();
    if (!L_str) return;
    const L = parseInt(L_str, 10);
    const C = parseInt(nextToken(), 10);

    const grid = [];
    const rowSums = [];
    const allVars = new Set();

    for (let i = 0; i < L; i++) {
        const row = [];
        for (let j = 0; j < C; j++) {
            const v = nextToken();
            row.push(v);
            allVars.add(v);
        }
        const s = parseInt(nextToken(), 10);
        grid.push(row);
        rowSums.push(s);
    }

    const colSums = [];
    for (let j = 0; j < C; j++) {
        colSums.push(parseInt(nextToken(), 10));
    }

    const totalVars = allVars.size;
    const knownValues = new Map();

    // Cria as equações: L linhas e C colunas
    const equations = [];
    for (let i = 0; i < L; i++) {
        equations.push({
            vars: grid[i],
            sum: rowSums[i]
        });
    }

    for (let j = 0; j < C; j++) {
        const colVars = [];
        for (let i = 0; i < L; i++) {
            colVars.push(grid[i][j]);
        }
        equations.push({
            vars: colVars,
            sum: colSums[j]
        });
    }

    while (knownValues.size < totalVars) {
        let found = false;
        for (let eq of equations) {
            const unknownCountMap = new Map();
            let knownSum = 0;

            for (let v of eq.vars) {
                if (knownValues.has(v)) {
                    knownSum += knownValues.get(v);
                } else {
                    unknownCountMap.set(v, (unknownCountMap.get(v) || 0) + 1);
                }
            }

            if (unknownCountMap.size === 1) {
                const [unknownVar, count] = unknownCountMap.entries().next().value;
                const value = (eq.sum - knownSum) / count;
                knownValues.set(unknownVar, Math.round(value));
                found = true;
                break;
            }
        }
        if (!found) break; // Segurança
    }

    const sortedVars = Array.from(knownValues.keys()).sort();
    let out = '';
    for (let v of sortedVars) {
        out += `${v} ${knownValues.get(v)}\n`;
    }
    process.stdout.write(out);
}

solve();
